import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, inviteAndJoin } from './helpers';

test.describe(`player: my status to automatically flip to idle when I'm not actively playing`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`a player's status shows idle once their snake game ends or they leave the game screen`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    // B's sidebar (self excluded) shows A's row -- observe A's status flips
    // from the room's point of view, not just A's own screen.
    const aRow = pageB.getByTestId('item-player_status').first();

    // A starts playing -- B sees "playing".
    await pageA.getByTestId('start-game-btn').click();
    await expect(aRow.getByText('playing')).toBeVisible({ timeout: 5_000 });

    // The game ends (wall collision) -- B sees "idle" again.
    await pageA.keyboard.press('ArrowUp');
    await expect(aRow.getByText('idle')).toBeVisible({ timeout: 5_000 });

    // A starts again, then leaves the game screen entirely (switches tabs)
    // -- B still sees idle, per "... or they leave the game screen".
    await pageA.getByTestId('start-game-btn').click();
    await expect(aRow.getByText('playing')).toBeVisible({ timeout: 5_000 });
    await pageA.getByTestId('tab-duels').click();
    await expect(aRow.getByText('idle')).toBeVisible({ timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });
});
